import { useEffect, useMemo, useState } from 'react';
import { Link, NavLink, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { Activity, AlertCircle, ArrowDownRight, ArrowLeftRight, ArrowUpRight, Boxes, Check, ChevronDown, Eye, EyeOff, ChevronLeft, ChevronRight, CircleHelp, ClipboardList, LayoutDashboard, LogOut, Menu, Package, Plus, RefreshCw, Search, ShieldAlert, ShieldCheck, ShoppingCart, Tags, Truck, UserRound, Users, X } from 'lucide-react';
import { toast } from 'sonner';
import { getErrorMessage, mapValidationErrors } from './api/axios.js';
import { authApi, resourceApi } from './api/services.js';
import { useAuth } from './auth/AuthContext.jsx';
import { PO_STATUS, TX_TYPES, stockStatus, toneClass } from './constants/badges.js';
import { formatCurrency, formatDate, formatNumber, formatTimestamp, relativeDate, refId, refName } from './utils/format.js';

const cx=(...s)=>s.filter(Boolean).join(' ');
const Button=({children,variant='primary',size='md',className='',...props})=><button className={cx('inline-flex items-center justify-center gap-2 rounded-lg font-medium transition-colors disabled:opacity-50 disabled:cursor-not-allowed',size==='sm'?'h-8 px-3 text-xs':size==='lg'?'h-11 px-5':'h-10 px-4 text-sm',variant==='primary'?'bg-accent-solid text-white hover:bg-accent-hover':variant==='danger'?'bg-danger-solid text-white hover:bg-red-500':variant==='soft-danger'?'border border-bad/40 text-bad hover:bg-bad/10':variant==='ghost'?'text-ink-2 hover:bg-elevated hover:text-ink':'border border-line-strong bg-elevated text-ink hover:bg-[#222E4D]',className)} {...props}>{children}</button>;
const IconButton=({label,children,className='',...p})=><button aria-label={label} title={label} className={cx('inline-flex h-9 w-9 items-center justify-center rounded-lg text-ink-3 hover:bg-elevated hover:text-ink',className)} {...p}>{children}</button>;
const Panel=({title,description,action,children,className=''})=><section className={cx('overflow-hidden rounded-xl border border-line bg-panel shadow-panel',className)}>{title&&<header className="flex items-center justify-between gap-3 border-b border-line px-5 py-4"><div><h2 className="text-sm font-semibold text-ink">{title}</h2>{description&&<p className="mb-0 mt-1 text-xs text-ink-3">{description}</p>}</div>{action}</header>}{children}</section>;
const Badge=({children,tone='muted'})=><span className={cx('inline-flex items-center rounded-full px-2.5 py-1 text-xs font-medium ring-1 ring-inset',toneClass[tone]||toneClass.muted)}>{children}</span>;
const Field=({label,required,error,children,hint})=><label className="block space-y-1.5"><span className="block text-xs font-medium text-ink-2">{label}{required&&<b className="ml-1 text-bad">*</b>}</span>{children}{error&&<span className="block text-xs text-bad">{error}</span>}{hint&&!error&&<span className="block text-xs text-ink-3">{hint}</span>}</label>;
const Input=(props)=><input {...props} className={cx('h-10 w-full rounded-lg border border-line bg-input px-3 text-sm text-ink placeholder:text-ink-3 focus:border-accent focus:ring-2 focus:ring-accent/25',props.className)}/>;
function PasswordInput({label='password',className='',...props}){const [visible,setVisible]=useState(false);return <div className="relative"><Input {...props} type={visible?'text':'password'} className={cx('pr-11',className)}/><button type="button" aria-label={`${visible?'Hide':'Show'} ${label}`} aria-pressed={visible} title={`${visible?'Hide':'Show'} ${label}`} onClick={()=>setVisible(current=>!current)} className="absolute right-1 top-1 grid h-8 w-8 place-items-center rounded-md text-ink-3 hover:bg-elevated hover:text-ink focus-visible:outline focus-visible:outline-2 focus-visible:outline-accent">{visible?<EyeOff size={17}/>:<Eye size={17}/>}</button></div>}
const Select=(props)=><select {...props} className={cx('h-10 w-full rounded-lg border border-line bg-input px-3 text-sm text-ink focus:border-accent focus:ring-2 focus:ring-accent/25',props.className)}/>;
const Textarea=(props)=><textarea {...props} className={cx('min-h-24 w-full rounded-lg border border-line bg-input px-3 py-2 text-sm text-ink placeholder:text-ink-3 focus:border-accent focus:ring-2 focus:ring-accent/25',props.className)}/>;
const ErrorState=({error,retry})=><div className="flex min-h-48 flex-col items-center justify-center p-8 text-center"><AlertCircle className="mb-3 text-bad"/><h3 className="font-medium text-ink">We couldn’t load this</h3><p className="mb-4 mt-1 max-w-sm text-sm text-ink-3">{getErrorMessage(error)}</p><Button variant="secondary" onClick={retry}><RefreshCw size={15}/>Try again</Button></div>;
const EmptyState=({title='Nothing here yet',detail='Items will appear here when available',action})=><div className="flex min-h-44 flex-col items-center justify-center p-8 text-center"><div className="mb-3 rounded-full bg-elevated p-3 text-ink-3"><Boxes size={20}/></div><h3 className="font-medium text-ink">{title}</h3><p className="mb-0 mt-1 text-sm text-ink-3">{detail}</p>{action&&<div className="mt-4">{action}</div>}</div>;
const Loading=()=> <div className="space-y-3 p-5" aria-label="Loading">{[0,1,2,3].map(i=><div key={i} className="h-12 animate-pulse rounded-lg bg-elevated"/>)}</div>;
function useRequest(loader,deps=[]){const [state,setState]=useState({loading:true,data:null,error:null});const [tick,setTick]=useState(0);useEffect(()=>{let live=true;setState(s=>({...s,loading:true,error:null}));loader().then(data=>live&&setState({loading:false,data,error:null})).catch(error=>live&&setState({loading:false,data:null,error}));return()=>{live=false}},[tick,...deps]);return {...state,retry:()=>setTick(n=>n+1),setData:(data)=>setState({loading:false,data,error:null})}}
const extract=(result,key,plural)=>{const resource=result?.[key]; if(Array.isArray(resource))return {rows:resource,pagination:null}; if(resource&&typeof resource==='object'){const rows=resource[plural]||resource[key]||[];return {rows,pagination:resource.pagination||null}}return {rows:[],pagination:null}};
const nice=(s='')=>s.replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase());
const actionLabel=(s='Activity')=>s.toLowerCase().replaceAll('_',' ').replace(/^./,x=>x.toUpperCase());
const userHasPermission=(user,permission)=>user?.role==='admin'||(user?.role==='employee'&&user?.permissions?.includes(permission));

function App(){
 const {user,loading,logout}=useAuth(); const location=useLocation(); const [drawer,setDrawer]=useState(false); const [logoutConfirm,setLogoutConfirm]=useState(false);
 useEffect(()=>{setDrawer(false)},[location.pathname]);
 if(loading)return <div className="grid min-h-screen place-items-center"><div className="h-8 w-8 animate-spin rounded-full border-2 border-line border-t-accent"/></div>;
 return user?<div className="min-h-screen bg-app lg:flex"><Sidebar drawer={drawer} close={()=>setDrawer(false)} user={user} askLogout={()=>setLogoutConfirm(true)}/><div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b border-line bg-sidebar/90 px-4 backdrop-blur sm:px-6"><div className="flex items-center gap-3"><IconButton label="Open navigation" className="lg:hidden" onClick={()=>setDrawer(true)}><Menu/></IconButton><div className="text-sm text-ink-3">StockPilot <span className="px-1">/</span><span className="text-ink">{pageTitle(location.pathname)}</span></div></div><UserChip user={user}/></header><main className="mx-auto w-full max-w-[1440px] px-4 py-6 sm:px-6 lg:px-8"><Routes><Route path="/" element={<Dashboard/>}/><Route path="/products" element={<ResourcePage kind="products"/>}/><Route path="/products/new" element={<ResourceForm kind="products"/>}/><Route path="/products/:id/edit" element={<ResourceForm kind="products"/>}/><Route path="/products/:id" element={<ProductDetail/>}/><Route path="/categories" element={<ResourcePage kind="categories"/>}/><Route path="/categories/new" element={<ResourceForm kind="categories"/>}/><Route path="/categories/:id/edit" element={<ResourceForm kind="categories"/>}/><Route path="/categories/:id" element={<ResourceDetail kind="categories"/>}/><Route path="/suppliers" element={<ResourcePage kind="suppliers"/>}/><Route path="/suppliers/new" element={<ResourceForm kind="suppliers"/>}/><Route path="/suppliers/:id/edit" element={<ResourceForm kind="suppliers"/>}/><Route path="/suppliers/:id" element={<ResourceDetail kind="suppliers"/>}/><Route path="/purchase-orders" element={<AdminOnly permission="purchase-orders:manage"><PurchaseOrders/></AdminOnly>}/><Route path="/purchase-orders/new" element={<AdminOnly permission="purchase-orders:manage"><PurchaseOrderForm/></AdminOnly>}/><Route path="/purchase-orders/:id/edit" element={<AdminOnly permission="purchase-orders:manage"><PurchaseOrderEdit/></AdminOnly>}/><Route path="/purchase-orders/:id" element={<AdminOnly permission="purchase-orders:manage"><PurchaseOrderDetail/></AdminOnly>}/><Route path="/inventory" element={<InventoryHub/>}/><Route path="/inventory/:operation" element={<InventoryForm/>}/><Route path="/transactions" element={<Transactions/>}/><Route path="/admin" element={<AdminOnly><AdminPanel/></AdminOnly>}/><Route path="/profile" element={<Profile/>}/><Route path="/403" element={<Denied/>}/><Route path="*" element={<NotFound/>}/></Routes></main></div>{logoutConfirm&&<Confirm title="Sign out of StockPilot?" detail="You’ll need to sign in again to manage inventory." action="Sign out" onCancel={()=>setLogoutConfirm(false)} onConfirm={async()=>{try{await logout();setLogoutConfirm(false)}catch(e){toast.error(getErrorMessage(e))}}}/>}</div>:<AuthRoutes/>;
}

const NAV_ICONS={LayoutDashboard,Package,Tags,Truck,ClipboardList,ArrowLeftRight,Activity,UserRound};
function Sidebar({drawer,close,user,askLogout}){
 useEffect(()=>{if(!drawer)return;const onKey=event=>{if(event.key==='Escape')close()};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[drawer,close]);
 return <><div onClick={close} className={cx('fixed inset-0 z-30 bg-black/60 transition-opacity lg:hidden',drawer?'opacity-100':'pointer-events-none opacity-0')}/><aside role={drawer?'dialog':undefined} aria-modal={drawer?'true':undefined} aria-label={drawer?'Primary navigation':undefined} onKeyDown={event=>{if(event.key==='Tab'){const items=[...event.currentTarget.querySelectorAll('a,button')].filter(item=>!item.disabled);if(items.length){const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}}} className={cx('fixed inset-y-0 left-0 z-40 flex w-[264px] flex-col border-r border-line bg-sidebar transition-transform duration-300 lg:sticky lg:top-0 lg:h-screen lg:translate-x-0',drawer?'translate-x-0':'-translate-x-full')}>
  <div className="flex h-16 items-center gap-3 border-b border-line px-5"><div className="grid h-9 w-9 place-items-center rounded-lg bg-accent-solid text-white"><Boxes size={20}/></div><div><div className="font-semibold text-ink">StockPilot</div><div className="text-[10px] text-ink-3">INVENTORY</div></div><IconButton label="Close navigation" className="ml-auto lg:hidden" onClick={close}><X/></IconButton></div>
  <nav className="flex-1 space-y-6 overflow-y-auto px-3 py-5">{NAV.map(group=>{const visibleItems=group.items.filter(([, , ,rule])=>!rule||user?.role==='admin'||user?.permissions?.includes(rule));if(!visibleItems.length)return null;return <div key={group.group}><div className="mb-1 px-3 text-[10px] font-semibold uppercase tracking-widest text-ink-3">{group.group}</div><div className="space-y-1">{visibleItems.map(([label,path,iconName])=>{const Icon=NAV_ICONS[iconName]||Boxes;return <NavLink key={path} to={path} end={path==='/'} className={({isActive})=>cx('relative flex h-10 items-center gap-3 rounded-lg px-3 text-sm transition-colors',isActive?'bg-accent-soft text-ink':'text-ink-2 hover:bg-elevated/60 hover:text-ink')}><Icon size={17} className="text-accent"/>{label}</NavLink>})}</div></div>})}</nav>
  <div className="border-t border-line p-4"><div className="flex items-center gap-3"><Avatar user={user}/><div className="min-w-0 flex-1"><div className="truncate text-sm font-medium text-ink">{user?.name}</div><Badge tone={user?.role==='admin'?'accent':'muted'}>{user?.role||'employee'}</Badge></div><IconButton label="Sign out" onClick={askLogout}><LogOut size={17}/></IconButton></div></div>
 </aside></>;
}const NAV=[{group:'Overview',items:[['Dashboard','/','LayoutDashboard']]},{group:'Catalog',items:[['Products','/products','Package'],['Categories','/categories','Tags'],['Suppliers','/suppliers','Truck']]},{group:'Operations',items:[['Purchase orders','/purchase-orders','ClipboardList','purchase-orders:manage'],['Inventory','/inventory','ArrowLeftRight'],['Transactions','/transactions','Activity','transactions:read']]},{group:'Administration',items:[['Admin panel','/admin','ShieldCheck','admin']]},{group:'Account',items:[['Profile','/profile','UserRound']]}];
function Avatar({user}){return <div className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-accent-soft text-xs font-semibold uppercase text-accent">{(user?.name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('')}</div>}
function UserChip({user}){return <div className="hidden items-center gap-2 sm:flex"><Avatar user={user}/><div><div className="text-xs font-medium text-ink">{user?.name}</div><div className="text-[11px] capitalize text-ink-3">{user?.role}</div></div></div>}
function pageTitle(path){if(path==='/')return 'Dashboard';return nice(path.split('/')[1]||'Dashboard').replaceAll('-',' ')}

function AuthRoutes(){const [register,setRegister]=useState(false);return <div className="min-h-screen bg-app lg:grid lg:grid-cols-2"><section className="relative hidden overflow-hidden border-r border-line bg-sidebar p-12 lg:flex lg:flex-col lg:justify-center"><div className="absolute inset-0 opacity-[.06]" style={{backgroundImage:'radial-gradient(var(--accent) 1px, transparent 1px)',backgroundSize:'22px 22px'}}/><div className="relative mx-auto max-w-md"><div className="mb-12 flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-lg bg-accent-solid text-white"><Boxes/></div><span className="text-lg font-semibold text-ink">StockPilot</span></div><h1 className="mb-4 text-4xl font-semibold tracking-tight">Know exactly what’s on your shelves.</h1><p className="mb-10 text-base text-ink-2">A clear view of inventory, purchasing and stock movement.</p><div className="space-y-4 text-sm text-ink-2"><p className="flex items-center gap-3"><Package size={18} className="text-accent"/>Keep your catalog organised</p><p className="flex items-center gap-3"><Activity size={18} className="text-accent"/>Track every stock change</p><p className="flex items-center gap-3"><ClipboardList size={18} className="text-accent"/>Stay on top of purchasing</p></div></div></section><section className="flex min-h-screen items-center justify-center p-5"><div className="w-full max-w-sm"><div className="mb-8 flex items-center gap-3 lg:hidden"><div className="grid h-9 w-9 place-items-center rounded-lg bg-accent-solid text-white"><Boxes size={19}/></div><b className="text-ink">StockPilot</b></div><AuthForm register={register} toggle={()=>setRegister(x=>!x)}/></div></section></div>}
function AuthForm({register,toggle}){const {login,register:signUp}=useAuth();const navigate=useNavigate();const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [fields,setFields]=useState({name:'',email:'',password:''});const submit=async e=>{e.preventDefault();setBusy(true);setError('');try{register?await signUp({name:fields.name,email:fields.email,password:fields.password}):await login({email:fields.email,password:fields.password});navigate('/')}catch(err){setError(getErrorMessage(err))}finally{setBusy(false)}};return <><div className="mb-7"><div className="text-xs font-semibold uppercase tracking-widest text-accent">Inventory operations</div><h1 className="mb-2 mt-2 text-2xl font-semibold text-ink">{register?'Create your account':'Welcome back'}</h1><p className="mb-0 text-sm">{register?'Set up your StockPilot account.':'Sign in to continue to your workspace.'}</p></div>{error&&<Banner>{error}</Banner>}<form className="space-y-4" onSubmit={submit}>{register&&<Field label="Full name" required><Input required minLength={3} maxLength={50} value={fields.name} onChange={e=>setFields({...fields,name:e.target.value})} autoComplete="name"/></Field>}<Field label="Email address" required><Input type="email" required value={fields.email} onChange={e=>setFields({...fields,email:e.target.value})} autoComplete="email"/></Field><Field label="Password" required><PasswordInput label="password" required minLength={register?8:1} value={fields.password} onChange={e=>setFields({...fields,password:e.target.value})} autoComplete={register?'new-password':'current-password'}/></Field><Button className="w-full" disabled={busy}>{busy?'Please wait…':register?'Create account':'Sign in'}</Button></form><p className="mt-6 text-center text-sm">{register?'Already have an account?':'New to StockPilot?'} <button className="font-medium text-accent hover:text-accent-2" onClick={toggle}>{register?'Sign in':'Create account'}</button></p><p className="mt-4 text-center text-xs text-ink-3">Registration uses the backend’s default employee role.</p></>}
function Banner({children}){return <div role="alert" className="mb-4 rounded-lg border border-bad/30 bg-bad/10 px-3 py-2.5 text-sm text-bad">{children}</div>}
function Confirm({title,detail,action='Confirm',onCancel,onConfirm}){return <Modal title={title} onClose={onCancel}><div className="p-5"><p className="mb-5 text-sm">{detail}</p><div className="flex justify-end gap-2"><Button variant="secondary" onClick={onCancel}>Cancel</Button><Button variant="danger" onClick={onConfirm}>{action}</Button></div></div></Modal>}
function Modal({title,onClose,children}){useEffect(()=>{const h=e=>e.key==='Escape'&&onClose?.();window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h)},[onClose]);return <div className="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4" onMouseDown={e=>e.target===e.currentTarget&&onClose?.()}><section role="dialog" aria-modal="true" aria-label={title} className="w-full max-w-lg overflow-hidden rounded-xl border border-line-strong bg-elevated shadow-pop"><header className="flex items-center justify-between border-b border-line px-5 py-4"><h2 className="text-sm font-semibold text-ink">{title}</h2><IconButton label="Close" onClick={onClose}><X size={18}/></IconButton></header>{children}</section></div>}

function PageHeader({title,subtitle,action,eyebrow}){return <div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div>{eyebrow&&<div className="mb-1 text-xs text-ink-3">{eyebrow}</div>}<h1 className="mb-1 text-2xl font-semibold tracking-tight text-ink">{title}</h1>{subtitle&&<p className="mb-0 text-sm text-ink-3">{subtitle}</p>}</div>{action}</div>}

function Dashboard(){
 const {user}=useAuth();
 const isAdmin=user?.role==='admin';
 const req=useRequest(()=>resourceApi.dashboard());
 const [lastRefreshed,setLastRefreshed]=useState(null);
 const [selectedTransaction,setSelectedTransaction]=useState(null);
 useEffect(()=>{if(!req.loading&&!req.error&&req.data)setLastRefreshed(new Date())},[req.loading,req.error,req.data]);
 const data=req.data?.dashboard;
 const inv=data?.inventory||{};
 const inventoryStats=[
  ['Total products',inv.totalProducts,'Package','accent'],
  ['Active products',inv.activeProducts,'Check','ok'],
  ['Low stock',inv.lowStockProducts,'AlertCircle','warn','/products?stock=LOW_STOCK'],
  ['Out of stock',inv.outOfStockProducts,'ShieldAlert','bad','/products?stock=OUT_OF_STOCK'],
  ['Inventory value',formatCurrency(inv.inventoryValue),'Activity','accent2'],
  ['Suppliers / categories',`${formatNumber(data?.totalSuppliers)} / ${formatNumber(data?.totalCategories)}`,'Tags','accent'],
 ];
 const purchasingStats=isAdmin?[
   ['Pending POs',data?.pendingPurchaseOrders,'ClipboardList','violet'],
   ['Partially received',data?.partiallyReceivedPurchaseOrders,'ArrowLeftRight','accent2'],
  ]:[];
 return <>
  <PageHeader title="Dashboard" eyebrow={`Welcome back, ${(user?.name||'').split(' ')[0]}`} subtitle={isAdmin?"Inventory health, stock movement and purchasing at a glance.":"Inventory health and stock movement at a glance."} action={<div className="flex items-center gap-3"><span className="hidden text-xs text-ink-3 sm:block">Last refreshed {lastRefreshed?formatTimestamp(lastRefreshed):'—'}</span><IconButton label="Refresh dashboard" onClick={req.retry}><RefreshCw size={17}/></IconButton></div>}/>
  {req.error?<Panel><ErrorState error={req.error} retry={req.retry}/></Panel>:req.loading?<Loading/>:<>
   <section aria-labelledby="inventory-overview-heading"><div className="mb-3 flex items-center gap-3"><h2 id="inventory-overview-heading" className="mb-0 text-sm font-semibold text-ink">Inventory overview</h2><div className="h-px flex-1 bg-line"/></div><div className="grid grid-cols-2 gap-3 md:grid-cols-3">{inventoryStats.map(([label,value,icon,tone,to])=><StatCard key={label} label={label} value={value??0} icon={icon} tone={tone} to={to}/>)}</div></section>
   {isAdmin&&<section aria-labelledby="purchasing-heading" className="mt-5"><div className="mb-3 flex items-center gap-3"><h2 id="purchasing-heading" className="mb-0 text-sm font-semibold text-ink">Purchasing</h2><div className="h-px flex-1 bg-line"/></div><div className="grid grid-cols-2 gap-3">{purchasingStats.map(([label,value,icon,tone])=><StatCard key={label} label={label} value={value??0} icon={icon} tone={tone}/>)}</div></section>}
   <div className="mt-5 grid gap-5 xl:grid-cols-12">
    <Panel title="Inventory movement" description="Daily inbound and outbound quantities for the last seven days." className="xl:col-span-8"><InventoryMovement rows={data?.inventoryMovement||[]}/></Panel>
    <Panel title="Stock health" description="Availability across active products." className="xl:col-span-4"><StockHealth inventory={inv}/></Panel>
   </div>
   {isAdmin&&<div className="mt-5"><Panel title="Recent transactions" action={<Link to="/transactions" className="text-xs font-medium text-accent hover:text-accent-2">View all</Link>}><RecentTransactions rows={data?.recentTransactions||[]} onSelect={setSelectedTransaction}/></Panel></div>}
   {isAdmin&&<div className="mt-5"><Panel title="Recent purchase orders" action={<Link to="/purchase-orders" className="text-xs font-medium text-accent hover:text-accent-2">View all</Link>}><RecentPOs rows={data?.recentPurchaseOrders||[]}/></Panel></div>}
   {selectedTransaction&&<TransactionDetailsModal transaction={selectedTransaction} onClose={()=>setSelectedTransaction(null)}/>}
  </>}
 </>;
}
function InventoryMovement({rows}){
 const max=Math.max(1,...rows.flatMap(row=>[Number(row.stockIn)||0,Number(row.stockOut)||0]));
 const hasMovements=rows.some(row=>(Number(row.stockIn)||0)+(Number(row.stockOut)||0)>0);
 return <div className="p-5">
  <div className="mb-4 flex justify-end gap-4 text-xs text-ink-2"><span className="inline-flex items-center gap-2"><i className="h-2.5 w-2.5 rounded-sm bg-ok"/>Inbound units</span><span className="inline-flex items-center gap-2"><i className="h-2.5 w-2.5 rounded-sm bg-bad"/>Outbound units</span></div>
  <div className="grid grid-cols-7 gap-2" role="img" aria-label="Daily inbound and outbound quantities for the last seven days">
   {rows.map(row=>{const date=new Date(`${row.date}T00:00:00Z`);const label=new Intl.DateTimeFormat(undefined,{weekday:'short',timeZone:'UTC'}).format(date);const incoming=Number(row.stockIn)||0;const outgoing=Number(row.stockOut)||0;return <div key={row.date} className="min-w-0 text-center" title={`${row.date}: ${incoming} inbound changes, ${outgoing} outbound changes`}>
    <div className="relative flex h-48 items-end justify-center gap-1 rounded-lg bg-elevated/40 px-1 pb-2">
     <div className="w-full max-w-8 rounded-t bg-ok transition-[height]" aria-label={`${incoming} inbound units`} title={`${incoming} inbound units`} style={{height:incoming?`${Math.max(6,(incoming/max)*100)}%`:'2px'}}/>
     <div className="w-full max-w-8 rounded-t bg-bad transition-[height]" aria-label={`${outgoing} outbound units`} title={`${outgoing} outbound units`} style={{height:outgoing?`${Math.max(6,(outgoing/max)*100)}%`:'2px'}}/>
    </div>
    <div className="mt-2 text-[11px] text-ink-3">{label}</div>
    <div className="text-[10px] tabular-nums text-ink-3">{date.getUTCDate()}</div>
    <div className="mt-1 whitespace-nowrap text-[10px] tabular-nums"><span className="text-ok">+{incoming}</span><span className="text-ink-3"> / </span><span className="text-bad">−{outgoing}</span></div>
   </div>})}
  </div>
  {!hasMovements&&<p className="mb-0 mt-3 text-center text-xs text-ink-3">No inventory changes recorded in the last seven days.</p>}
 </div>;
}function StatCard({label,value,icon,tone,to}){const Icon=({Package,Check,AlertCircle,ShieldAlert,Activity,ClipboardList,ArrowLeftRight,Tags}[icon])||Package;const color={accent:'text-accent bg-accent/10',accent2:'text-accent-2 bg-accent-2/10',ok:'text-ok bg-ok/10',warn:'text-warn bg-warn/10',bad:'text-bad bg-bad/10',violet:'text-violet-300 bg-violet-400/10'}[tone];const Card=to?Link:'div';return <Card {...(to?{to}: {})} className={cx('block rounded-xl border border-line bg-panel p-4 shadow-panel sm:p-5',to&&'transition-colors hover:border-line-strong hover:bg-elevated/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent')}><div className="flex items-center justify-between gap-2"><div className="text-[11px] font-semibold uppercase tracking-wider text-ink-3">{label}</div><div className={cx('grid h-9 w-9 place-items-center rounded-lg',color)}><Icon size={18}/></div></div><div className="mt-3 truncate text-2xl font-semibold tabular-nums tracking-tight text-ink sm:text-3xl">{value}</div>{to&&<span className="mt-2 flex items-center gap-1 text-xs font-medium text-ink-3">View products <ArrowUpRight size={13}/></span>}</Card>}
function StockHealth({inventory}){
 const total=Math.max(0,Number(inventory?.activeProducts)||0);
 if(!total)return <EmptyState title="No active products" detail="Stock health appears when products are active."/>;
 const low=Math.min(total,Math.max(0,Number(inventory?.lowStockProducts)||0));
 const out=Math.min(total-low,Math.max(0,Number(inventory?.outOfStockProducts)||0));
 const inStock=total-low-out;
 const slices=[['In stock',inStock,'var(--success)','bg-ok'],['Low stock',low,'var(--warning)','bg-warn'],['Out of stock',out,'var(--danger)','bg-bad']];
 const radius=82, circumference=2*Math.PI*radius;
 let offset=0;
 const segments=slices.map(([name,value,color])=>{
  const length=(value/total)*circumference;
  const segment={name,value,color,length,offset};
  offset+=length;
  return segment;
 });
 return <div className="p-5">
  <div className="relative mx-auto w-full max-w-[220px]">
   <svg viewBox="0 0 220 220" className="block h-auto w-full" role="img" aria-label={`Stock health: ${inStock} in stock, ${low} low stock, ${out} out of stock`}>
    {segments.map(segment=><circle key={segment.name} cx="110" cy="110" r={radius} fill="none" stroke={segment.color} strokeWidth="34" strokeDasharray={`${segment.length} ${circumference-segment.length}`} strokeDashoffset={-segment.offset} transform="rotate(-90 110 110)"/>)}
   </svg>
   <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
    <div className="text-3xl font-semibold tabular-nums text-ink">{formatNumber(total)}</div>
    <div className="text-xs text-ink-3">active products</div>
   </div>
  </div>
  <div className="mx-auto mt-4 max-w-xs space-y-2">
   {slices.map(([name,value,,dotClass])=><div key={name} className="flex items-center justify-between gap-3 text-xs">
    <span className="flex items-center gap-2 text-ink-2"><i className={cx('h-2 w-2 shrink-0 rounded-full',dotClass)}/>{name}</span>
    <span className="shrink-0 tabular-nums text-ink">{formatNumber(value)} <span className="text-ink-3">({Math.round(value/total*100)}%)</span></span>
   </div>)}
  </div>
 </div>
}
