 return <div className="divide-y divide-line/70">{rows.slice(0,8).map((tx,i)=>{const [label,tone]=TX_TYPES[tx.type]||[tx.type,'muted'];const plus=['PURCHASE','RETURN'].includes(tx.type)||(tx.type==='ADJUSTMENT'&&tx.newQuantity>=tx.previousQuantity);return <button type="button" key={tx._id||i} onClick={()=>onSelect?.(tx)} className="flex w-full items-center gap-3 px-5 py-3 text-left hover:bg-elevated/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"><div className="min-w-0 flex-1"><div className="truncate text-sm font-medium text-ink">{refName(tx.product)}</div><div className="text-xs text-ink-3">{tx.product?.sku||'—'} · {relativeDate(tx.createdAt)}</div></div><Badge tone={tone}>{label}</Badge><div className={cx('w-20 text-right text-sm font-medium tabular-nums',plus?'text-ok':'text-bad')}>{plus?'+':'−'}{formatNumber(tx.quantity)}</div><span className="sr-only">View transaction details</span></button>})}</div>;
